//! Byte-oriented parser for a one-byte key and a `u16` decimal value.

/// Errors returned by [`parse_pair`].
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ParseError {
    /// The input is absent or does not have the required `key=value` shape.
    InvalidFormat,
    /// The decimal value exceeds the range of a `u16`.
    Overflow,
}

impl core::fmt::Display for ParseError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            Self::InvalidFormat => f.write_str("invalid pair format"),
            Self::Overflow => f.write_str("pair value overflows u16"),
        }
    }
}

impl std::error::Error for ParseError {}

/// Parses a byte sequence as a one-byte key, `=`, and a decimal `u16` value.
///
/// The key may be any byte. The input must contain at least one digit and is
/// treated as a byte sequence, not as text or a NUL-terminated string.
pub fn parse_pair(input: Option<&[u8]>) -> Result<(u8, u16), ParseError> {
    let input = input.ok_or(ParseError::InvalidFormat)?;
    if input.len() < 3 || input[1] != b'=' {
        return Err(ParseError::InvalidFormat);
    }

    let mut number: u32 = 0;
    for &byte in &input[2..] {
        if !byte.is_ascii_digit() {
            return Err(ParseError::InvalidFormat);
        }
        number = number * 10 + u32::from(byte - b'0');
        if number > u32::from(u16::MAX) {
            return Err(ParseError::Overflow);
        }
    }

    Ok((input[0], number as u16))
}

#[cfg(test)]
mod tests {
    use super::{parse_pair, ParseError};

    #[test]
    fn maps_original_c_assertions() {
        assert_eq!(parse_pair(Some(&[0xff, b'=', b'9'])), Ok((0xff, 9)));
        assert_eq!(parse_pair(Some(b"a=00")), Ok((b'a', 0)));
        assert_eq!(parse_pair(Some(b"a=65535")), Ok((b'a', u16::MAX)));
        assert_eq!(parse_pair(None), Err(ParseError::InvalidFormat));
        assert_eq!(parse_pair(Some(b"a=")), Err(ParseError::InvalidFormat));
        assert_eq!(parse_pair(Some(b"a=1x")), Err(ParseError::InvalidFormat));
        assert_eq!(parse_pair(Some(b"a=65536")), Err(ParseError::Overflow));
        assert_eq!(parse_pair(Some(b"a=655360x")), Err(ParseError::Overflow));
    }

    #[test]
    fn preserves_format_and_overflow_precedence() {
        assert_eq!(parse_pair(Some(b"a=65536x")), Err(ParseError::Overflow));
        assert_eq!(
            parse_pair(Some(b"a=1x65536")),
            Err(ParseError::InvalidFormat)
        );
        assert_eq!(parse_pair(Some(b"==0")), Ok((b'=', 0)));
        assert_eq!(parse_pair(Some(b"a=\0")), Err(ParseError::InvalidFormat));
    }
}

