//! Split text into nonempty lines using Python's `str.splitlines` boundaries.

/// Returns each nonempty line verbatim, using Python's `str.splitlines`
/// separator set.
///
/// Recognized separators are LF, CR, CRLF, vertical tab, form feed, file/group/
/// record separators (U+001C–U+001E), NEL, line separator, and paragraph
/// separator. A CRLF pair is one boundary. A terminal boundary does not create
/// an extra trailing line, and whitespace within lines is preserved.
pub fn split_nonempty(input: &str) -> Vec<String> {
    let mut lines = Vec::new();
    let mut start = 0;
    let mut chars = input.char_indices().peekable();

    while let Some((index, ch)) = chars.next() {
        if is_line_separator(ch) {
            if start < index {
                lines.push(input[start..index].to_owned());
            }
            if ch == '\r' && chars.peek().is_some_and(|(_, next)| *next == '\n') {
                let (lf_index, lf) = chars.next().expect("peeked character exists");
                start = lf_index + lf.len_utf8();
            } else {
                start = index + ch.len_utf8();
            }
        }
    }

    if start < input.len() {
        lines.push(input[start..].to_owned());
    }
    lines
}

fn is_line_separator(ch: char) -> bool {
    matches!(
        ch,
        '\n' | '\r' | '\x0b' | '\x0c' | '\x1c'..='\x1e' | '\u{0085}' | '\u{2028}' | '\u{2029}'
    )
}

#[cfg(test)]
mod tests {
    use super::split_nonempty;

    #[test]
    fn python_separators() {
        for separator in [
            "\n", "\r", "\r\n", "\u{000b}", "\u{000c}", "\u{001c}", "\u{001d}", "\u{001e}",
            "\u{0085}", "\u{2028}", "\u{2029}",
        ] {
            assert_eq!(
                split_nonempty(&format!("a{separator}b{separator}")),
                ["a", "b"]
            );
        }
    }

    #[test]
    fn whitespace_is_not_trimmed() {
        assert_eq!(split_nonempty(" a \n \nb "), [" a ", " ", "b "]);
    }

    #[test]
    fn empty_lines_are_removed() {
        assert!(split_nonempty("\n\r\n").is_empty());
        assert!(split_nonempty("").is_empty());
    }

    #[test]
    fn other_control_characters_are_content() {
        assert_eq!(split_nonempty("a\u{001f}b"), ["a\u{001f}b"]);
    }
}

